independent.solution:
count = 0
total = 0
while True:
    line = input()
    if line == "end":
        break
    score = int(line)
    if score < 0 or score > 100:
        continue
    count += 1
    total += score
print("Count:", count)
if count == 0:
    print("Average: n/a")
else:
    print("Average:", round(total / count, 1))

limit = 90
candidate = limit + 1
while True:
    for d in range(2, candidate):
        if candidate % d == 0:
            break
    else:
        print("First prime after", str(limit) + ":", candidate)
        break
    candidate += 1

n = 27
steps = 0
peak = n
while n != 1:
    if n % 2 == 0:
        n = n // 2
    else:
        n = 3 * n + 1
    steps += 1
    if n > peak:
        peak = n
print("Steps:", steps)
print("Peak:", peak)
